function validate([compressed]) {
  if (compressed.length < 1 || compressed.length > 60000) return 'compressed needs 1 to 6 * 10^4 characters.';
  if (!/^(?:[a-z][1-9][0-9]*)+$/.test(compressed)) return 'compressed must be groups of one lowercase letter followed by a count without leading zeros.';
  if (compressed.match(/[0-9]+/g).some(digits => Number(digits) > 10000)) return 'Each count is from 1 to 10^4.';
  return null;
}

