function betterCompression(compressed) {
  const base = 'a'.charCodeAt(0);
  // total[c] is the combined count of the letter whose code is base + c.
  const total = new Array(26).fill(0);
  let i = 0;
  while (i < compressed.length) {
    const letter = compressed.charCodeAt(i) - base;
    i++;
    let count = 0;
    while (i < compressed.length && compressed[i] >= '0' && compressed[i] <= '9') {
      count = count * 10 + Number(compressed[i]);
      i++;
    }
    total[letter] += count;
  }
  let result = '';
  for (let c = 0; c < 26; c++) {
    if (total[c] > 0) {
      result += String.fromCharCode(base + c) + total[c];
    }
  }
  return result;
}

