function betterCompression(compressed) {
  // Cut the string into "letter + digits" pieces with a regular expression, add them up per letter, then sort the letters.
  const sums = {};
  for (const piece of compressed.match(/[a-z][0-9]+/g)) {
    sums[piece[0]] = (sums[piece[0]] || 0) + parseInt(piece.slice(1), 10);
  }
  return Object.keys(sums).sort().map(letter => letter + sums[letter]).join('');
}

