function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  // Draw from a few random letters (small inputs) or many (large ones), so letters repeat across groups.
  const alphabet = 'abcdefghijklmnopqrstuvwxyz'.split('');
  for (let i = alphabet.length - 1; i > 0; i--) {
    const j = int(0, i);
    [alphabet[i], alphabet[j]] = [alphabet[j], alphabet[i]];
  }
  const letters = alphabet.slice(0, large ? int(3, 26) : int(1, 5));
  // Mostly short counts, sometimes long ones, including the largest allowed count.
  const count = () => {
    const r = rand();
    return r < 0.55 ? int(1, 9) : r < 0.8 ? int(10, 999) : r < 0.95 ? int(1000, 9999) : 10000;
  };
  // Groups are at most 6 characters, so a large input stays under the app's 10,000 characters.
  const target = large ? 9990 : int(2, 30);
  let compressed = '';
  while (compressed.length < target) compressed += letters[int(0, letters.length - 1)] + count();
  return [compressed];
}
